$('#generateForm').onsubmit=async e=>{e.preventDefault();const month=$('#generateMonth').value,cat=$('#generateCategory').value,eligible=players.filter(p=>p.status==='active'&&(!cat||playerCatIds(p).includes(cat)));try{const existing=new Set(charges.filter(c=>c.month===month).map(c=>`${c.playerId}|${c.month}`)),batch=writeBatch(db);let count=0;for(const p of eligible){if(existing.has(`${p.id}|${month}`))continue;const c=categories.find(x=>x.id===p.categoryId),amount=Number(p.customFee||c?.fee||0);batch.set(doc(db,'charges',`${p.id}_${month}`),{orgId:ORG_ID,playerId:p.id,playerCode:p.playerCode,categoryId:p.categoryId,userIds:p.linkedUserIds||[],month,amount,paidAmount:0,status:'pending',dueDay:15,dueDate:dueDateForMonth(month),createdAt:serverTimestamp(),updatedAt:serverTimestamp()});count++}if(count)await batch.commit();$('#generateDialog').close();await loadAdminData();toast(`${count} mensualidades generadas.`)}catch(x){alert(err(x))}};

function availableSinpeCharges(){return familyCharges.filter(c=>['pending','partial'].includes(c.status)&&chargeRemaining(c)>0&&!activeReportForCharge(c.id))}
function populateSinpeMonths(){
  const playerId=$('#sinpePlayer').value,list=availableSinpeCharges().filter(c=>c.playerId===playerId).sort((a,b)=>(b.month||'').localeCompare(a.month||''));
  $('#sinpeMonth').innerHTML=list.map(c=>`<option value="${c.id}">${esc(monthLabel(c.month))} · Saldo ${money(chargeRemaining(c))}${chargeDueState(c)==='overdue'?' · Morosa':''}</option>`).join('');
  const c=list[0];$('#sinpeCharge').value=c?.id||'';$('#sinpeAmount').value=c?chargeRemaining(c):'';$('#sinpeSubmitButton').disabled=!c;
}
$('#openSinpeButton').onclick=()=>{
  const available=availableSinpeCharges(),playerIds=[...new Set(available.map(c=>c.playerId))];
  if(!available.length)return alert('No hay mensualidades disponibles para reportar. Los meses pagados o con un reporte pendiente no pueden pagarse nuevamente.');
  $('#sinpeForm').reset();$('#sinpePlayer').innerHTML=playerIds.map(id=>`<option value="${id}">${esc(playerName(id))}</option>`).join('');
  $('#sinpeDate').value=today();$('#sinpePhone').value=profile.phone||'';$('#sinpePayer').value=profile.fullName||'';populateSinpeMonths();$('#sinpeDialog').showModal();
};
$('#sinpePlayer').onchange=populateSinpeMonths;
$('#sinpeMonth').onchange=()=>{const id=$('#sinpeMonth').value,c=familyCharges.find(x=>x.id===id);$('#sinpeCharge').value=id;if(c)$('#sinpeAmount').value=chargeRemaining(c)};
$('#sinpeForm').onsubmit=async e=>{e.preventDefault();const b=$('#sinpeSubmitButton');try{const c=familyCharges.find(x=>x.id===$('#sinpeCharge').value);if(!c)throw Error('Selecciona una mensualidad.');if(!['pending','partial'].includes(c.status)||chargeRemaining(c)<=0)throw Error('Esta mensualidad ya no tiene saldo pendiente.');if(activeReportForCharge(c.id))throw Error('Ya existe un pago reportado o aprobado para esta mensualidad.');const amount=Number($('#sinpeAmount').value),remaining=chargeRemaining(c);if(amount<=0||amount>remaining)throw Error(`El monto debe estar entre ₡1 y ${money(remaining)}.`);busy(b,true,'Enviando…');await addDoc(collection(db,'sinpeReports'),{orgId:ORG_ID,userId:auth.currentUser.uid,chargeId:c.id,playerId:c.playerId,playerCode:c.playerCode,month:c.month,amount,date:$('#sinpeDate').value,time:$('#sinpeTime').value,bank:$('#sinpeBank').value.trim(),phone:$('#sinpePhone').value.trim(),payerName:$('#sinpePayer').value.trim(),reference:$('#sinpeReference').value.trim(),notes:$('#sinpeNotes').value.trim(),status:'reported',createdAt:serverTimestamp(),updatedAt:serverTimestamp()});$('#sinpeDialog').close();await loadFamilyData();toast('SINPE reportado para revisión.')}catch(x){alert(err(x))}finally{busy(b,false)}};
async function approveSinpe(id){if(!confirm('¿Aprobar y aplicar este SINPE?'))return;try{const s=sinpeReports.find(x=>x.id===id),c=charges.find(x=>x.id===s.chargeId);if(!s||!c)throw Error('No se encontró la mensualidad asociada.');if(s.status!=='reported')throw Error('Este reporte ya fue procesado.');const remaining=chargeRemaining(c);if(remaining<=0)throw Error('Esta mensualidad ya está pagada.');const applied=Math.min(Number(s.amount||0),remaining),paid=Number(c.paidAmount||0)+applied,status=paid>=Number(c.amount||0)?'paid':'partial';const batch=writeBatch(db);batch.update(doc(db,'charges',c.id),{paidAmount:paid,status,updatedAt:serverTimestamp()});batch.update(doc(db,'sinpeReports',id),{status:'approved',approvedBy:auth.currentUser.uid,approvedAt:serverTimestamp(),updatedAt:serverTimestamp()});await batch.commit();await loadAdminData();toast('SINPE aprobado.')}catch(x){alert(err(x))}}
async function rejectSinpe(id){const reason=prompt('Motivo del rechazo:')||'';try{await updateDoc(doc(db,'sinpeReports',id),{status:'rejected',rejectionReason:reason,updatedAt:serverTimestamp()});await loadAdminData();toast('SINPE rechazado.')}catch(x){alert(err(x))}}

